import React from "react";
import { GameMode } from "../AuthContext";

// Mock state
let mockState: any = {
  isAuthenticated: false,
  user: null,
  playerData: null,
  currentRiddle: null,
  gameMode: "daily" as GameMode,
  isDailyChallengeAvailable: false,
  isLoading: false,
};

// Mock functions
const mockFunctions = {
  setGameMode: jest.fn((mode: GameMode) => {
    mockState.gameMode = mode;
  }),
  setCurrentRiddle: jest.fn((riddle: any) => {
    mockState.currentRiddle = riddle;
  }),
  updatePlayerData: jest.fn(async (updates: any) => {
    if (mockState.playerData) {
      mockState.playerData = { ...mockState.playerData, ...updates };
    }
  }),
  updatePlayerClassicIndex: jest.fn(async (index: number) => {
    if (mockState.playerData && mockState.playerData.progress) {
      mockState.playerData.progress.classicIndex = index;
    }
  }),
  logout: jest.fn(async () => {
    mockState.isAuthenticated = false;
    mockState.user = null;
    mockState.playerData = null;
    mockState.currentRiddle = null;
  }),
};

// Mock hook
export const useAuth = jest.fn(() => ({
  ...mockState,
  ...mockFunctions,
}));

// Mock provider
export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  return <>{children}</>;
};

// Export GameMode from the original module
export type { GameMode } from "../AuthContext";

// Expose mock helpers for tests
export const __setMockState = (newState: any) => {
  mockState = { ...mockState, ...newState };
};

export const __resetMockState = () => {
  mockState = {
    isAuthenticated: false,
    user: null,
    playerData: null,
    currentRiddle: null,
    gameMode: "daily" as GameMode,
    isDailyChallengeAvailable: false,
    isLoading: false,
  };
  Object.values(mockFunctions).forEach((fn: any) => fn.mockClear());
};

export const __getMockFunctions = () => mockFunctions;
